insert into public.cars (name, brand, model, year, category, description, price_per_day, transmission, fuel_type, seating_capacity, mileage, features, image_urls, availability_status, is_featured, bookings_count) values
('Aurelia GT', 'Aurelia', 'GT Coupe', 2024, 'Sports', 'A grand tourer built for long, fast, effortless days. Twin-turbo V8 power, a hand-stitched leather cabin and a chassis tuned for coastal roads.', 289.00, 'Automatic', 'Petrol', 2, '9 km/l', array['Leather interior','Adaptive suspension','Heated seats','Apple CarPlay','Parking sensors','Bluetooth'], array['/images/cars/aurelia-gt.svg','/images/cars/aurelia-gt-2.svg','/images/cars/aurelia-gt-3.svg'], 'available', true, 41),
('Meridian S', 'Meridian', 'S 450', 2024, 'Luxury', 'The executive saloon for airport transfers and business weeks. Quiet, composed and fitted with rear-seat comfort controls.', 219.00, 'Automatic', 'Hybrid', 5, '16 km/l', array['Massage seats','Panoramic roof','Rear-seat climate','Adaptive cruise','Wireless charging','Premium audio'], array['/images/cars/meridian-s.svg','/images/cars/meridian-s-2.svg','/images/cars/meridian-s-3.svg'], 'available', true, 63),
('Vanguard X', 'Vanguard', 'X7 Sport', 2023, 'SUV', 'Seven seats, serious luggage space and permanent all-wheel drive. Suited to family trips and mountain roads alike.', 169.00, 'Automatic', 'Diesel', 7, '12 km/l', array['All-wheel drive','7 seats','Roof rails','360 camera','Tow bar','Child seat anchors'], array['/images/cars/vanguard-x.svg','/images/cars/vanguard-x-2.svg','/images/cars/vanguard-x-3.svg'], 'available', true, 52),
('Solstice R', 'Solstice', 'R Performance', 2024, 'Sports', 'Track-bred handling in a road-legal package. Rear-wheel drive, a manual gearbox and an exhaust note worth the detour.', 329.00, 'Manual', 'Petrol', 2, '8 km/l', array['Sport exhaust','Carbon trim','Launch control','Bucket seats','Brembo brakes'], array['/images/cars/solstice-r.svg','/images/cars/solstice-r-2.svg','/images/cars/solstice-r-3.svg'], 'available', false, 28),
('Nordic E', 'Nordic', 'E-Saloon 80', 2025, 'Electric', 'A calm, fast electric saloon with around 500 km of real-world range and fast-charging support. Charge cable included.', 149.00, 'Automatic', 'Electric', 5, '500 km range', array['Fast charging','Autopilot assist','Glass roof','Heat pump','Over-the-air updates'], array['/images/cars/nordic-e.svg','/images/cars/nordic-e-2.svg','/images/cars/nordic-e-3.svg'], 'available', true, 47),
('Terra 4x4', 'Terra', 'Trail Edition', 2023, 'SUV', 'Go where the tarmac stops. High ground clearance, locking differentials and a roof tent mount for weekend expeditions.', 159.00, 'Manual', 'Diesel', 5, '11 km/l', array['4x4 low range','Skid plates','Roof tent mount','Off-road tyres','Winch ready'], array['/images/cars/terra-4x4.svg','/images/cars/terra-4x4-2.svg','/images/cars/terra-4x4-3.svg'], 'available', false, 19),
('Capri Spider', 'Capri', 'Spider 2.0', 2024, 'Convertible', 'Roof down, coast road ahead. A light, agile two-seat roadster with a fully automatic fabric hood.', 199.00, 'Automatic', 'Petrol', 2, '13 km/l', array['Power soft-top','Wind deflector','Heated seats','Sport mode','Premium audio'], array['/images/cars/capri-spider.svg','/images/cars/capri-spider-2.svg','/images/cars/capri-spider-3.svg'], 'available', true, 36),
('Atlas Van', 'Atlas', 'Traveller 9', 2023, 'Van', 'Nine seats for groups, weddings and airport runs. Sliding doors, rear air-conditioning and generous luggage space.', 129.00, 'Manual', 'Diesel', 9, '10 km/l', array['9 seats','Rear A/C','Sliding doors','Large boot','USB in every row'], array['/images/cars/atlas-van.svg','/images/cars/atlas-van-2.svg','/images/cars/atlas-van-3.svg'], 'available', false, 22),
('Lumen EV', 'Lumen', 'Urban Electric', 2025, 'Electric', 'Compact, quick and silent in town. Ideal for city breaks with easy parking and very low running costs.', 99.00, 'Automatic', 'Electric', 5, '380 km range', array['City braking assist','Fast charging','Lane assist','Reversing camera'], array['/images/cars/lumen-ev.svg','/images/cars/lumen-ev-2.svg','/images/cars/lumen-ev-3.svg'], 'available', false, 31),
('Regent L', 'Regent', 'L Chauffeur', 2024, 'Luxury', 'Our flagship limousine for weddings and VIP travel. Optional chauffeur, privacy glass and a lounge-style rear cabin.', 399.00, 'Automatic', 'Petrol', 4, '7 km/l', array['Privacy glass','Rear lounge seating','Champagne cooler','Air suspension','Ambient lighting'], array['/images/cars/regent-l.svg','/images/cars/regent-l-2.svg','/images/cars/regent-l-3.svg'], 'available', true, 17),
('Horizon SUV', 'Horizon', 'Crossover 5', 2024, 'SUV', 'A comfortable five-seat crossover with hybrid efficiency. The sensible, stylish choice for most trips.', 119.00, 'Automatic', 'Hybrid', 5, '18 km/l', array['Hybrid drive','Keyless entry','Roof rails','Lane assist','Apple CarPlay / Android Auto'], array['/images/cars/horizon-suv.svg','/images/cars/horizon-suv-2.svg','/images/cars/horizon-suv-3.svg'], 'available', false, 58),
('Pulse Hatch', 'Pulse', 'City 1.2', 2023, 'Sedan', 'Easy, economical and fun. The smart pick for daily errands, students and tight city streets.', 59.00, 'Manual', 'Petrol', 5, '20 km/l', array['Bluetooth','USB charging','Air conditioning','Reversing sensors'], array['/images/cars/pulse-hatch.svg','/images/cars/pulse-hatch-2.svg','/images/cars/pulse-hatch-3.svg'], 'available', false, 74);
insert into public.testimonials (customer_name, review, rating, is_featured) values
('Priya Sharma', 'Booking took two minutes and the car was waiting exactly where we agreed. The Meridian felt brand new.', 5, true),
('Daniel Okafor', 'Clear pricing, no surprises at pickup. I have rented three times now and each handover was quick.', 5, true),
('Sofia Marchetti', 'We took the Capri along the coast for a long weekend. Flawless, and support answered within minutes.', 5, true),
('James Whitfield', 'Needed a seven-seater at short notice. The Vanguard was ready the same afternoon.', 4, true);
